create extension if not exists pgcrypto;
create table if not exists public.cars(id uuid primary key default gen_random_uuid(),name text not null,category text,price_per_km numeric(10,2),seats integer,luggage text,image_url text,features text[] default '{}',active boolean default true,created_at timestamptz default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),title text not null,description text,icon text,active boolean default true,created_at timestamptz default now());
create table if not exists public.routes(id uuid primary key default gen_random_uuid(),pickup text not null,destination text not null,distance text,travel_time text,one_way_price numeric(10,2),round_trip_price numeric(10,2),active boolean default true,created_at timestamptz default now());
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),customer_name text not null,city text,rating integer default 5 check(rating between 1 and 5),review text not null,active boolean default true,created_at timestamptz default now());
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),name text not null,mobile text not null,pickup text not null,destination text not null,booking_date date not null,pickup_time time not null,trip_type text not null,passengers integer default 1,notes text,status text default 'new',created_at timestamptz default now());
create table if not exists public.site_settings(id integer primary key default 1,business_name text default 'Tejas Taxi',phone text,whatsapp text,email text,address text,hero_title text default 'Your journey. Our commitment.',hero_description text,hero_image_url text,about_text text,updated_at timestamptz default now(),constraint single_settings_row check(id=1));
insert into public.site_settings(id,business_name,hero_title) values(1,'Tejas Taxi','Your journey. Our commitment.') on conflict(id) do nothing;
alter table public.cars enable row level security;alter table public.services enable row level security;alter table public.routes enable row level security;alter table public.reviews enable row level security;alter table public.bookings enable row level security;alter table public.site_settings enable row level security;
drop policy if exists public_read_cars on public.cars;create policy public_read_cars on public.cars for select to anon,authenticated using(active=true);drop policy if exists admin_cars on public.cars;create policy admin_cars on public.cars for all to authenticated using(true) with check(true);
drop policy if exists public_read_services on public.services;create policy public_read_services on public.services for select to anon,authenticated using(active=true);drop policy if exists admin_services on public.services;create policy admin_services on public.services for all to authenticated using(true) with check(true);
drop policy if exists public_read_routes on public.routes;create policy public_read_routes on public.routes for select to anon,authenticated using(active=true);drop policy if exists admin_routes on public.routes;create policy admin_routes on public.routes for all to authenticated using(true) with check(true);
drop policy if exists public_read_reviews on public.reviews;create policy public_read_reviews on public.reviews for select to anon,authenticated using(active=true);drop policy if exists admin_reviews on public.reviews;create policy admin_reviews on public.reviews for all to authenticated using(true) with check(true);
drop policy if exists public_insert_bookings on public.bookings;create policy public_insert_bookings on public.bookings for insert to anon,authenticated with check(true);drop policy if exists admin_bookings on public.bookings;create policy admin_bookings on public.bookings for all to authenticated using(true) with check(true);
drop policy if exists public_read_settings on public.site_settings;create policy public_read_settings on public.site_settings for select to anon,authenticated using(true);drop policy if exists admin_settings on public.site_settings;create policy admin_settings on public.site_settings for all to authenticated using(true) with check(true);
